#include <atomic>
#include <chrono>

#include "zelda_gz.h"
#include "librecomp/helpers.hpp"
#include "librecomp/overlays.hpp"
#include "librecomp/game.hpp"

#ifdef ZELDA64_OOT_GZ
// Generated by oot/tools/gen_gz.py.
#include "gz_info.h"
#include "gz_image_bin.h"

// gz functions called by the patches, from the recompiled gz code.
extern "C" {
    void gz__disp_hook(uint8_t* rdram, recomp_context* ctx);
    void gz__input_hook(uint8_t* rdram, recomp_context* ctx);
    void gz__ocarina_update_hook(uint8_t* rdram, recomp_context* ctx);
}
#endif

static std::atomic_bool gz_started = false;

bool zelda64::gz::available() {
#ifdef ZELDA64_OOT_GZ
    return true;
#else
    return false;
#endif
}

void zelda64::gz::set_started(bool started) {
    gz_started = started && available();
}

bool zelda64::gz::started() {
    return gz_started;
}

void zelda64::gz::on_init(uint8_t* rdram, recomp_context* ctx) {
#ifdef ZELDA64_OOT_GZ
    // Load the gz image and clear its bss, which gz's loader would do on console. This is done even when gz isn't
    // started, as its hooks are always in the game and read its state to know that it isn't running.
    gpr image_vram = (int32_t)GZ_IMAGE_VRAM;
    for (size_t i = 0; i < sizeof(gz_image_bin); i++) {
        MEM_B(i, image_vram) = gz_image_bin[i];
    }
    for (uint32_t addr = GZ_BSS_START; addr < GZ_BSS_END; addr++) {
        MEM_B(0, (gpr)(int32_t)addr) = 0;
    }

    // Make gz's functions available to indirect calls, as gz uses function pointers extensively.
    load_overlays(GZ_TEXT_ROM, (int32_t)GZ_TEXT_VRAM, GZ_TEXT_SIZE);
#else
    (void)rdram;
    (void)ctx;
#endif
}

// Called by the recompiled gz hooks to check whether gz is running.
extern "C" int zelda64_gz_active(void) {
    return gz_started;
}

// Functions called by the patches that replace functions gz hooks into.
extern "C" void recomp_gz_active(uint8_t* rdram, recomp_context* ctx) {
    _return<s32>(ctx, gz_started);
}

extern "C" void recomp_gz_disp_hook(uint8_t* rdram, recomp_context* ctx) {
#ifdef ZELDA64_OOT_GZ
    gz__disp_hook(rdram, ctx);
#endif
}

extern "C" void recomp_gz_input_hook(uint8_t* rdram, recomp_context* ctx) {
#ifdef ZELDA64_OOT_GZ
    gz__input_hook(rdram, ctx);
#endif
}

extern "C" void recomp_gz_ocarina_update_hook(uint8_t* rdram, recomp_context* ctx) {
#ifdef ZELDA64_OOT_GZ
    gz__ocarina_update_hook(rdram, ctx);
#endif
}

#ifdef ZELDA64_OOT_GZ
// gz functions reimplemented natively (see oot/tools/gen_gz.py).

// Returns the CPU counter, which gz reads directly for its timer.
extern "C" void gz__clock_ticks(uint8_t* rdram, recomp_context* ctx) {
    static const auto start = std::chrono::steady_clock::now();
    constexpr uint64_t counter_rate = 46875000; // OS_CPU_COUNTER
    uint64_t ns = std::chrono::duration_cast<std::chrono::nanoseconds>(std::chrono::steady_clock::now() - start).count();
    uint64_t ticks = (ns / 1000000000ULL) * counter_rate + (ns % 1000000000ULL) * counter_rate / 1000000000ULL;
    _return<u32>(ctx, (u32)ticks);
}

// Reports that there's no flashcart or SD card adapter, as gz accesses those through PI registers.
extern "C" void gz__io_init(uint8_t* rdram, recomp_context* ctx) {
    _return<s32>(ctx, -1);
}

// Reads from the cartridge, which gz does through the PI registers. gz uses this to read compressed files from the
// ROM when saving and loading states. Only the ROM is supported, and anything else reads as zero.
extern "C" void gz__pi_read_locked(uint8_t* rdram, recomp_context* ctx) {
    constexpr uint32_t rom_base = 0x10000000;
    uint32_t dev_addr = _arg<0, u32>(rdram, ctx) & 0x1FFFFFFF;
    gpr dst = ctx->r5;
    uint32_t size = _arg<2, u32>(rdram, ctx);

    std::span<const uint8_t> rom = recomp::get_rom();
    for (uint32_t i = 0; i < size; i++) {
        uint32_t addr = dev_addr + i;
        uint8_t value = 0;
        if (addr >= rom_base && addr - rom_base < rom.size()) {
            value = rom[addr - rom_base];
        }
        MEM_B(i, dst) = value;
    }
}

extern "C" void gz__pi_read(uint8_t* rdram, recomp_context* ctx) {
    gz__pi_read_locked(rdram, ctx);
}

// Writes to the cartridge, which is only used for flashcarts and SD card adapters, so it's ignored.
extern "C" void gz__pi_write_locked(uint8_t* rdram, recomp_context* ctx) {
}

extern "C" void gz__pi_write(uint8_t* rdram, recomp_context* ctx) {
}
#endif
